:root {
  --ink: #24332d;
  --paper: #fffdf5;
  --sage: #dce7cf;
  --moss: #46634f;
  --clay: #bd6f4f;
  --ochre: #dba947;
  --ash: #d6d0c2;
  --line: #c9d2c2;
  --muted: #6b766d;
}

.intake-card {
  box-sizing: border-box;
  width: 500px;
  height: 278px;
  display: grid;
  grid-template-rows: 62px 1fr 46px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  background: var(--sage);
  border-bottom: 1px solid var(--line);
}

.site-mark {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  color: var(--paper);
  background: var(--moss);
  border-radius: 50%;
  line-height: 1;
}

.mark-ring {
  font-size: 13px;
}

.site-code {
  margin-top: 2px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: .08em;
}

.heading-group {
  flex: 1;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .05em;
  text-transform: uppercase;
}

.card-title {
  margin: 0;
  font-size: 21px;
  font-weight: 800;
  line-height: 1;
  letter-spacing: -.03em;
}

.received-status {
  padding: 6px 8px;
  color: var(--moss);
  background: var(--paper);
  border: 1px solid var(--moss);
  border-radius: 5px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.intake-body {
  display: grid;
  grid-template-columns: 108px 1fr;
  gap: 14px;
  padding: 12px 16px 10px;
}

.core-figure {
  display: grid;
  grid-template-columns: 24px 46px 28px;
  align-items: center;
  justify-content: center;
  margin: 0;
  padding-right: 12px;
  border-right: 1px solid var(--line);
}

.core-label,
.depth-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .07em;
  writing-mode: vertical-rl;
}

.core-label {
  transform: rotate(180deg);
}

.core-tube {
  display: flex;
  flex-direction: column;
  height: 112px;
  overflow: hidden;
  background: var(--ash);
  border: 2px solid var(--ink);
  border-radius: 8px;
}

.layer {
  display: block;
  width: 100%;
}

.layer-top {
  height: 24%;
  background: var(--moss);
}

.layer-clay {
  height: 29%;
  background: var(--clay);
}

.layer-ash {
  height: 18%;
  background: var(--ash);
}

.layer-base {
  flex: 1;
  background: var(--ochre);
}

.sample-panel {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.sample-topline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--line);
}

.sample-id {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  letter-spacing: .04em;
}

.priority-tag {
  padding: 3px 6px;
  color: var(--paper);
  background: var(--clay);
  border-radius: 4px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: .06em;
}

.reading-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  padding: 9px 0;
}

.reading {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.reading-label {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.reading-value {
  font-size: 17px;
  font-weight: 800;
  line-height: 1;
}

.field-note {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: auto 0 0;
  padding: 6px 8px;
  color: var(--ink);
  background: var(--sage);
  border-radius: 5px;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
}

.note-dot {
  flex: 0 0 auto;
  width: 7px;
  height: 7px;
  background: var(--clay);
  border-radius: 50%;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
  background: var(--paper);
  border-top: 1px solid var(--line);
}

.custody-line {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
}

.custody-line strong {
  color: var(--ink);
  font-weight: 800;
}

.seal-button {
  padding: 7px 11px;
  color: var(--paper);
  background: var(--moss);
  border: 1px solid var(--moss);
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .02em;
}
